contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs driving c
    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public payable {
        // no precondition except that we may need some gas; allow any inputs
        require(true);

        // record test contract balance before the call
        uint balBefore = address(this).balance;

        // Attempt the call and capture whether it reverted and the return value if not
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // If _tos is empty the implementation requires length>0 and must revert.
        // Otherwise it should return true (per implementation) and must not change this contract's balance.
        if (_tos.length == 0) {
            assert(reverted == true);
        } else {
            assert(reverted == false && ret == true && address(this).balance == balBefore);
        }
    }

    // allow receiving Ether if some external call forwards funds
    receive() external payable { }
}

