contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // If the call to c.transfer does not revert then it returns true.
    // We restrict inputs so multiplication won't overflow and _tos is non-empty.
    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public payable {
        // require non-empty _tos because C.transfer requires it
        require(_tos.length > 0);
        // require that v * 10**_decimals does not overflow uint (safe bound)
        // 10**_decimals must be computable: limit _decimals so exponentiation won't overflow
        require(_decimals <= 77); // 10**78 > 2**256, so 77 is safe
        // additionally require that multiplication won't overflow
        if (v != 0) {
            uint multiplier = 10 ** _decimals;
            require(v <= type(uint).max / multiplier);
        }

        bool reverted;
        bool ret;

        // top-level state-changing call on c
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: if the call did not revert then returned value must be true
        assert(reverted || ret == true);
    }

    receive() external payable { }
}

