contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We receive Ether in case target calls forward value to this contract during c.transfer.
    receive() external payable { }

    // Inputs: from is arbitrary, target address to be called, array of tos, v and decimals
    // The test calls c.transfer and records whether it reverted; if it returned, the return value
    // must be true per the contract implementation. We assert the equivalence: not reverted => returned true.
    function run(address from, address caddress, address[] calldata _tos, uint v, uint _decimals) public payable {
        require(_tos.length >= 0);

        bool reverted;
        bool ret;
        // call and capture revert status
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: If the call did not revert then it must have returned true, and conversely
        // if it returned true then it did not revert. This ties the observable return to revert behavior.
        // Also ensure that a successful return implies that the input had at least one recipient (as contract requires).
        assert((!reverted && ret && _tos.length > 0) || (reverted && !ret));
    }
}

